<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientGrantTypesJsonAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientGrantTypesJsonAccessor trait.
 *
 * Covers null default, string/VO assignment via withGrantTypesJson,
 * getGrantTypesJson/grantTypesJson accessors, and isGrantTypesJsonChanged with/without original.
 */
class TrustedClientGrantTypesJsonAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withGrantTypesJson creates a new instance with the GrantTypesJson set
     * from a string value, and getGrantTypesJson returns the primitive string.
     */
    public function testWithGrantTypesJsonFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientGrantTypesJsonAccessorUnitTest();

        // Act
        $result = $holder->withGrantTypesJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getGrantTypesJson());
    }
    /**
     * Asserts that withgrantTypesJson has access to the value object
     * from a string value, and getGrantTypesJson returns the primitive string.
     */
    public function testWithGrantTypesJsonFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientGrantTypesJsonAccessorUnitTest();

        // Act
        $result = $holder->withGrantTypesJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->grantTypesJson()->value());
    }
    public function testChangedGrantTypesJson(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientGrantTypesJsonAccessorUnitTest();
        $original = $holder->withGrantTypesJson('one');
        $same = $holder->withGrantTypesJson('one');
        $modified = $holder->withGrantTypesJson('other');

        // Act
        $unchanged = $holder->isGrantTypesJsonChanged();
        $withSame = $original->isGrantTypesJsonChanged($same);
        $withDiferent = $original->isGrantTypesJsonChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientGrantTypesJsonAccessorUnitTest
{
    use TrustedClientGrantTypesJsonAccessor;
}
